// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address k) public {
        Bank bank = new Bank();
        // the caller is the Bank contract (supportsToken requires it) with zero balance
        vm.prank(address(bank));
        c.airDrop();
        // general rule: for every k, if k is the (zero-balance) caller of a successful
        // airDrop, then tokenBalance(k) must be nonzero afterwards (credited 20 tokens);
        // for k != caller it is trivially admissible. The mutant never credits, so
        // tokenBalance(bank) stays 0 and breaks the rule for k == caller.
        assertTrue(k != address(bank) || c.tokenBalance(k) != 0);
    }
}

contract Bank {
    function supportsToken() external pure returns (bytes32) {
        return keccak256(abi.encodePacked("Nu Token"));
    }
}

